<script setup lang="ts">
import { Input as InputPrimitive } from '@zeus-web/input/vue'
import { computed, useAttrs } from 'vue'

import { cn } from '@/lib/cn'

// @generated by scripts/generate-component-contracts.mjs:BEGIN
type InputSize = 'sm' | 'md' | 'lg'
type InputType =
  | 'text'
  | 'email'
  | 'password'
  | 'search'
  | 'tel'
  | 'url'
  | 'number'
interface InputRegistryProps {
  size?: InputSize
  type?: InputType
  class?: string
  id?: string
  value?: string
  defaultValue?: string
  placeholder?: string
  disabled?: boolean
  invalid?: boolean
  readonly?: boolean
  required?: boolean
  name?: string
  autocomplete?: string
  ariaLabel?: string
  ariaDescribedby?: string
  ariaErrormessage?: string
  formatter?: (value: string) => string
  modelValue?: string
}
interface InputRegistryEmits {
  (
    event: 'valueChange',
    payload: CustomEvent<{ value: string; nativeEvent: Event }>,
  ): void
  (
    event: 'focusChange',
    payload: CustomEvent<{ focused: boolean; nativeEvent: FocusEvent }>,
  ): void
  (event: 'update:modelValue', payload: string): void
}
defineOptions({
  inheritAttrs: false,
})
const props = withDefaults(defineProps<InputRegistryProps>(), {
  size: 'md',
  type: 'text',
  disabled: false,
  invalid: false,
  readonly: false,
  required: false,
})
const emit = defineEmits<InputRegistryEmits>()
// @generated by scripts/generate-component-contracts.mjs:END

const attrs = useAttrs()

const inputSizeClasses: Record<InputSize, string> = {
  sm: '[&_[part=root]]:h-8 [&_[part=root]]:px-2.5 [&_[part=root]]:text-xs',
  md: '[&_[part=root]]:h-9 [&_[part=root]]:px-3 [&_[part=root]]:text-sm',
  lg: '[&_[part=root]]:h-10 [&_[part=root]]:px-3.5 [&_[part=root]]:text-sm',
}

const classes = computed(() =>
  cn(
    'block w-full',
    '[&_[part=root]]:flex [&_[part=root]]:w-full [&_[part=root]]:min-w-0 [&_[part=root]]:items-center [&_[part=root]]:rounded-[var(--zeus-radius-md)] [&_[part=root]]:border [&_[part=root]]:border-[hsl(var(--zeus-input))] [&_[part=root]]:bg-[hsl(var(--zeus-background))] [&_[part=root]]:text-[hsl(var(--zeus-foreground))]',
    '[&_[data-slot=input]]:min-w-0 [&_[data-slot=input]]:flex-1 [&_[data-slot=input]]:border-0 [&_[data-slot=input]]:bg-transparent [&_[data-slot=input]]:outline-none [&_[data-slot=input]]:placeholder:text-[hsl(var(--zeus-muted-foreground))]',
    '[&_[part=root]:focus-within]:outline-none [&_[part=root]:focus-within]:ring-2 [&_[part=root]:focus-within]:ring-[hsl(var(--zeus-ring)/0.35)]',
    '[&[data-invalid]_[part=root]]:border-[hsl(var(--zeus-destructive))] [&[data-invalid]_[part=root]:focus-within]:ring-[hsl(var(--zeus-destructive)/0.35)]',
    'data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50',
    inputSizeClasses[props.size],
    props.class,
  ),
)

const mergedAttrs = computed(() => {
  const result: Record<string, unknown> = {
    ...attrs,
    id: props.id,
    defaultValue: props.defaultValue,
    type: props.type,
    disabled: props.disabled,
    readonly: props.readonly,
    required: props.required,
    name: props.name,
    autocomplete: props.autocomplete,
    ariaLabel: props.ariaLabel,
    ariaDescribedby: props.ariaDescribedby,
    ariaErrormessage: props.ariaErrormessage,
    formatter: props.formatter,
  }
  if (props.value !== undefined) {
    result.value = props.value
  }
  if (props.modelValue !== undefined) {
    result.value = props.modelValue
  }
  return result
})

function handleValueChange(
  event: CustomEvent<{ value: string; nativeEvent: Event }>,
) {
  const target = event.target as HTMLInputElement | null
  emit('valueChange', event)
  emit('update:modelValue', event.detail.value || target?.value || '')
}

function handleFocusChange(
  event: CustomEvent<{ focused: boolean; nativeEvent: FocusEvent }>,
) {
  emit('focusChange', event)
}
</script>

<template>
  <InputPrimitive
    v-bind="mergedAttrs"
    :size="props.size"
    :disabled="props.disabled"
    :invalid="props.invalid"
    :placeholder="props.placeholder"
    :class="classes"
    @value-change="handleValueChange"
    @focus-change="handleFocusChange"
  >
    <template #prefix>
      <slot name="prefix" />
    </template>
    <template #suffix>
      <slot name="suffix" />
    </template>
    <template #message>
      <slot name="message" />
    </template>
  </InputPrimitive>
</template>
